/**
 * SKB shared domain types.
 *
 * Conventions:
 *  - Monetary amounts are integers in **minor units** (e.g. piastres/cents). Never floats.
 *  - IDs are opaque strings (UUIDs) generated by the server.
 *  - Timestamps are ISO‑8601 strings when serialized over the wire.
 */

// ---------------------------------------------------------------------------
// Locale & presentation
// ---------------------------------------------------------------------------

export type Locale = 'en' | 'ar';
export type Direction = 'ltr' | 'rtl';
export type ThemeMode = 'light' | 'dark' | 'system';

/** Device class the adaptive shell renders for. */
export type DeviceClass = 'phone' | 'tablet' | 'desktop';
export type Platform = 'ios' | 'android' | 'windows' | 'macos' | 'web';

// ---------------------------------------------------------------------------
// Identity, roles & permissions
// ---------------------------------------------------------------------------

/** Coarse roles. Fine‑grained gating is done with Permission below. */
export type Role = 'OWNER' | 'ADMIN' | 'ACCOUNTANT' | 'SALES' | 'INVENTORY' | 'VIEWER';

export const ROLES: readonly Role[] = [
  'OWNER',
  'ADMIN',
  'ACCOUNTANT',
  'SALES',
  'INVENTORY',
  'VIEWER',
] as const;

/**
 * Permissions are action strings of the form `resource:action`.
 * The server is the single enforcer; the client uses them only to shape UI.
 */
export type Permission =
  | 'dashboard:view'
  | 'sales:view'
  | 'sales:create'
  | 'sales:edit'
  | 'sales:override_floor'
  | 'purchases:view'
  | 'purchases:create'
  | 'receipts:view'
  | 'receipts:create'
  | 'parties:view'
  | 'parties:edit'
  | 'inventory:view'
  | 'inventory:edit'
  | 'staff:view'
  | 'staff:manage'
  | 'branches:view'
  | 'branches:manage'
  | 'analytics:view'
  | 'settings:view'
  | 'settings:manage'
  | 'audit:view'
  | 'presence:view';

export interface Staff {
  id: string;
  fullName: string;
  email: string;
  role: Role;
  /** Branch the staff member is currently operating under. */
  branchId: string;
  isActive: boolean;
  phone?: string;
  createdAt: string;
}

/** The authenticated user as the client sees it (never includes secrets). */
export interface AuthUser {
  id: string;
  fullName: string;
  email: string;
  role: Role;
  branchId: string;
  permissions: Permission[];
}

export interface Branch {
  id: string;
  name: string;
  code: string;
  isActive: boolean;
  /** Human‑readable location / address line. */
  location?: string;
}

// ---------------------------------------------------------------------------
// Money & currency
// ---------------------------------------------------------------------------

export interface Money {
  /** Integer amount in minor units. */
  amount: number;
  /** ISO 4217 code, e.g. "EGP", "USD", "SAR". */
  currency: string;
}

// ---------------------------------------------------------------------------
// Parties (customers / suppliers / factories)
// ---------------------------------------------------------------------------

export type PartyType = 'CUSTOMER' | 'SUPPLIER' | 'FACTORY';

export interface Party {
  id: string;
  name: string;
  /** A party may hold more than one role (e.g. customer + supplier). */
  types: PartyType[];
  phone?: string;
  email?: string;
  taxNumber?: string;
  /**
   * Net balance in minor units.
   *  > 0  → they owe us (receivable, "لنا عليهم")
   *  < 0  → we owe them (payable,   "لهم علينا")
   *  = 0  → settled
   */
  balance: number;
  currency: string;
  isActive: boolean;
  createdAt: string;
}

/** Presentation‑ready balance so the UI never guesses the sign meaning. */
export type BalanceDirection = 'receivable' | 'payable' | 'settled';

export interface PartyBalanceView {
  direction: BalanceDirection;
  /** Absolute amount in minor units (always ≥ 0). */
  amount: number;
  currency: string;
}

// ---------------------------------------------------------------------------
// Inventory
// ---------------------------------------------------------------------------

export interface Category {
  id: string;
  name: string;
}

export interface Product {
  id: string;
  sku: string;
  name: string;
  categoryId: string;
  unit: string;
  /** Cost & sale price in minor units. */
  costPrice: number;
  salePrice: number;
  currency: string;
  /** Aggregate stock across branches (per‑branch stock is a separate query). */
  stockOnHand: number;
  reorderLevel: number;
  barcode?: string;
  isActive: boolean;
}

// ---------------------------------------------------------------------------
// Documents (sales / purchases / receipts)
// ---------------------------------------------------------------------------

export type DocumentType =
  | 'QUOTATION'
  | 'SALES_INVOICE'
  | 'SALES_RETURN'
  | 'PURCHASE_INVOICE'
  | 'PURCHASE_RETURN'
  | 'COLLECTION_RECEIPT'
  | 'PAYMENT_VOUCHER'
  | 'EXPENSE';

export type DocumentStatus =
  | 'DRAFT'
  | 'PENDING'
  | 'CONFIRMED'
  | 'PAID'
  | 'PARTIALLY_PAID'
  | 'OVERDUE'
  | 'CANCELLED'
  | 'RETURNED';

export interface DocumentLine {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  /** Unit price in minor units. */
  unitPrice: number;
  /** Line discount in minor units. */
  discount: number;
  /** quantity * unitPrice - discount (+ tax), in minor units. */
  lineTotal: number;
  /** Weighted-average cost per unit at posting time (COGS per unit), minor units. */
  unitCost: number;
  /** Line profit = lineTotal - (quantity * unitCost), minor units. */
  lineProfit: number;
}

export interface SalesDocument {
  id: string;
  /** Human document number, e.g. "INV-2026-000123". */
  number: string;
  type: DocumentType;
  status: DocumentStatus;
  branchId: string;
  branchName: string;
  partyId: string;
  partyName: string;
  /** Staff member who created the document (shown on the printed doc). */
  staffId: string;
  staffName: string;
  issueDate: string;
  dueDate?: string;
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  grandTotal: number;
  paidAmount: number;
  /** Cost of goods on the document (sum of line costs), minor units. */
  costTotal: number;
  /** Profit = (subtotal - discountTotal) - costTotal, minor units. Tax is pass-through. */
  profitTotal: number;
  currency: string;
  notes?: string;
  createdAt: string;
}

/** One row of the profitability report (a customer, a product, or a day). */
export interface ProfitRow {
  key: string;
  label: string;
  /** Net sales (subtotal − discount), minor units. */
  revenue: number;
  /** Cost of goods sold, minor units. */
  cost: number;
  /** Profit = revenue − cost, minor units. */
  profit: number;
  /** Invoice count (customer/day groupings). */
  invoices: number;
  /** Units sold (product grouping). */
  quantity: number;
}

export type ProfitGroupBy = 'customer' | 'product' | 'day';

/** Profitability report (تقارير الربحية) over a date range. */
export interface ProfitReport {
  from: string;
  to: string;
  by: ProfitGroupBy;
  currency: string;
  revenue: number;
  cost: number;
  profit: number;
  invoices: number;
  rows: ProfitRow[];
}

/** Company-wide pricing/costing defaults (Settings / الضبط). */
export interface CompanySettings {
  companyName: string;
  currency: string;
  /** Suggested markup for a new sales line (e.g. 10 → price = cost + 10%). */
  defaultMarkupPercent: number;
  /** Profit floor: sales blocked below cost × (1 + min/100); 0 = never below cost. */
  minMarkupPercent: number;
  /** Default sales tax percent for new invoices (0 = none). */
  defaultTaxPercent: number;
}

/** Lightweight row for list views (no line items). */
export interface SalesDocumentSummary {
  id: string;
  number: string;
  type: DocumentType;
  status: DocumentStatus;
  branchName: string;
  partyName: string;
  staffName: string;
  issueDate: string;
  dueDate?: string;
  grandTotal: number;
  paidAmount: number;
  currency: string;
}

// ---------------------------------------------------------------------------
// Dashboard
// ---------------------------------------------------------------------------

export interface KpiValue {
  key: string;
  /** Value in minor units when `isMoney`, else a plain count. */
  value: number;
  isMoney: boolean;
  currency?: string;
  /** Percentage change vs previous period, if computed. */
  deltaPct?: number;
  tone: 'positive' | 'warning' | 'destructive' | 'info' | 'neutral';
}

export interface TrendPoint {
  /** ISO date (day/period bucket). */
  date: string;
  sales: number;
  purchases: number;
}

export interface DashboardData {
  kpis: KpiValue[];
  trend: TrendPoint[];
  lowStock: Product[];
  recentDocuments: SalesDocumentSummary[];
  currency: string;
}

// ---------------------------------------------------------------------------
// Connection / sync state (UI‑level)
// ---------------------------------------------------------------------------

export type ConnectionState = 'online' | 'connecting' | 'offline';

// ---------------------------------------------------------------------------
// Audit & presence (server‑authoritative, foundation for owner/CEO view)
// ---------------------------------------------------------------------------

export interface AuditEntry {
  id: string;
  actorId: string;
  actorName: string;
  action: string;
  resource: string;
  resourceId?: string;
  branchId?: string;
  ip?: string;
  userAgent?: string;
  createdAt: string;
}

export interface PresenceEntry {
  userId: string;
  fullName: string;
  role: Role;
  branchId: string;
  /** What the user is currently looking at (route key), if reported. */
  currentView?: string;
  connectedAt: string;
  lastSeenAt: string;
}

// ---------------------------------------------------------------------------
// Generic API envelopes
// ---------------------------------------------------------------------------

export interface Paginated<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

export interface ApiError {
  statusCode: number;
  message: string;
  /** Machine‑readable code for the client to branch on. */
  code?: string;
}
